suppressPackageStartupMessages({library(ggplot2);library(patchwork);library(ggrastr)})
md<-load_meta();raw<-qread(file.path(old,'02_ucell_scores/M_RAW.qs'));usage<-qread(file.path(old,'02_ucell_scores/original_usage_raw.qs'));ids<-md$cell_id
md[,`:=`(UCell=raw[ids,'EpiMP10'],usage_display=log1p(usage[ids,'EpiMP10']),C8=ifelse(r04=='C8','C8','Other'),C12_C16=ifelse(r06%in%c('C12','C16'),r06,'Other'))]
