savep<-function(p,name,data,w=12,h=9,note=''){folder<-out('04_figures_by_dataset');pp<-file.path(folder,name);ggsave(paste0(pp,'.pdf'),p,width=w,height=h,bg='transparent',limitsize=FALSE);ggsave(paste0(pp,'.png'),p,width=w,height=h,dpi=300,bg='transparent',limitsize=FALSE);wt(data,paste0('04_figures_by_dataset/',name,'_plotdata.tsv.gz'));index[[length(index)+1L]]<<-data.table(figure=name,pdf=paste0(pp,'.pdf'),png=paste0(pp,'.png'),plot_data=paste0(pp,'_plotdata.tsv.gz'),note=note);wt(rbindlist(index),'04_figures_by_dataset/figure_index.tsv');logmsg('Figure',name)}
plasma<-function(limits,name)scale_color_viridis_c(option='plasma',limits=limits,name=name,na.value='grey70')
embs<-list(FULL_Z=qread(file.path(old,'03_full_z/umap.qs')));if(file.exists(out('00_audit/original_RNA_umap.qs')))embs$original_RNA<-qread(out('00_audit/original_RNA_umap.qs'))
climits<-list(UCell=range(md$UCell),usage_display=range(md$usage_display));wt(rbindlist(lapply(names(climits),function(x)data.table(metric=x,lower=climits[[x]][1],upper=climits[[x]][2],rule='FULL range; exact zero black; no clipping'))),'04_figures_by_dataset/color_limits.tsv')
for(en in names(embs)){em<-embs[[en]];d<-copy(md);d[,`:=`(x=em[cell_id,1],y=em[cell_id,2])];xl<-range(d$x);yl<-range(d$y)
 for(ds in scopes){a<-if(ds=='ALL')d else d[dataset==ds];plots<-list()
 for(v in c('C8','C12_C16')){aa<-a[order(get(v)!='Other')];plots[[v]]<-ggplot(aa,aes(x,y,color=.data[[v]]))+geom_point_rast(size=.13,raster.dpi=300)+scale_color_manual(values=c(Other='grey85',C8='#BD3786',C12='#3B528B',C16='#E16462'),drop=FALSE,name=if(v=='C8')'r0.4'else'r0.6')+coord_cartesian(xlim=xl,ylim=yl)+labs(x='UMAP 1',y='UMAP 2')+th+theme(axis.text=element_blank(),axis.ticks=element_blank())}
 for(v in c('UCell','usage_display'))plots[[v]]<-ggplot(a,aes(x,y))+geom_point_rast(data=a[get(v)==0],color='black',size=.13,raster.dpi=300)+geom_point_rast(data=a[get(v)>0],aes(color=.data[[v]]),size=.13,raster.dpi=300)+plasma(climits[[v]],if(v=='UCell')'MP10 UCell raw'else'log1p(MP10 usage raw)')+coord_cartesian(xlim=xl,ylim=yl)+labs(x='UMAP 1',y='UMAP 2')+th+theme(axis.text=element_blank(),axis.ticks=element_blank())
 savep(wrap_plots(plots,ncol=2)+plot_annotation(theme=theme(plot.background=element_rect(fill='transparent',colour=NA))),paste0(ds,'__',en,'__frozen_state_overlays'),a[,.(cell_id,sample,dataset,x,y,C8,C12_C16,UCell,usage_display)],11,9,'Frozen global coordinates; C8/r0.4 and C12,C16/r0.6 shown in separate panels. All cells plotted. Zero black. Continuous ranges fixed from FULL.')
 }}
pa<-fread(out('01_usage_bridge/sample_paired_14MP.tsv.gz'));pa<-merge(pa,samples,by='sample');us<-pa[scale=='usage_raw'&MP=='EpiMP10'&eligible==TRUE];umax<-max(abs(us$delta_mean));qc<-fread(out('03_marker_review/sample_group_QC.tsv'));qc<-merge(qc,samples,by='sample');e<-fread(out('00_audit/comparison_eligibility.tsv'));qc<-merge(qc,e[,.(sample,comparison,eligible)],by=c('sample','comparison'))
allshort<-fread(out('03_marker_review/all_shortlists.tsv'));expr<-fread(out('03_marker_review/shortlist_diagnostic_sample_contrasts.tsv.gz'));expr<-merge(expr,samples,by='sample');shkey<-unique(allshort[,.(comparison,gene_id)]);plotexpr<-merge(expr,shkey,by=c('comparison','gene_id'));plotexpr<-plotexpr[eligible==TRUE];longexpr<-rbind(plotexpr[,.(comparison,gene_id,sample,dataset,group='Left',expression=expr_left,detection=pct_left)],plotexpr[,.(comparison,gene_id,sample,dataset,group='Right',expression=expr_right,detection=pct_right)]);dotmax<-max(longexpr$expression)
diag<-fread(out('03_marker_review/MP07_MP10_per_gene_summary.tsv'));diag<-diag[comparison%in%c('r04_C8_vs_rest','r06_C12_vs_rest','r06_C16_vs_rest')];diagmax<-max(c(diag$expr_left,diag$expr_right));
for(ds in scopes){u<-if(ds=='ALL')us else us[dataset==ds]
 if(nrow(u)){p<-ggplot(u,aes(sample_code,delta_mean,color=source))+geom_hline(yintercept=0,color='grey65')+geom_point(size=1.7)+facet_wrap(~comparison,ncol=2,scales='free_x',drop=FALSE)+coord_cartesian(ylim=c(-umax,umax))+labs(x='Sample code (see key)',y='Within-sample mean MP10 usage: Left - Right')+th+theme(axis.text.x=element_text(angle=90,hjust=1));savep(p,paste0(ds,'__MP10_usage_paired_deltas'),u,13,10,'Only eligible pairs, all their cells; same raw usage axis limits. Missing panels have zero eligible pairs.')}else{p<-ggplot()+annotate('text',x=0,y=0,label='No eligible paired samples (both groups >=30 cells)')+theme_void();savep(p,paste0(ds,'__MP10_usage_paired_deltas'),data.table(scope=ds,n_eligible=0),10,3,'Dataset retained; no paired inference.')}
 q<-qc[comparison%in%c('r04_C8_vs_rest','r06_C12_vs_C16') & eligible==TRUE];if(ds!='ALL')q<-q[dataset==ds];if(nrow(q)){q[,display_mean:=ifelse(metric=='percent.mt',mean,log1p(mean))];p<-ggplot(q,aes(group,display_mean,group=sample,color=source))+geom_line(alpha=.4)+geom_point(size=.9)+facet_wrap(comparison~metric,scales='free_y',ncol=3)+labs(x=NULL,y='Sample mean (counts/features: log1p; mt: percent)')+th;savep(p,paste0(ds,'__paired_QC'),q,12,7,'Eligible pairs only; no QC regression or cell filtering.')}
 d<-if(ds=='ALL')longexpr else longexpr[dataset==ds];if(nrow(d)){d<-d[,.(expression=mean(expression),detection=mean(detection),n_samples=uniqueN(sample)),by=.(comparison,gene_id,group)];d[,label:=paste0(group,' (N=',n_samples,')')];p<-ggplot(d,aes(label,gene_id,size=detection))+geom_point(data=d[expression>0],aes(color=expression))+geom_point(data=d[expression==0],color='black')+plasma(c(0,dotmax),'Mean RNA log-normalized')+scale_size_continuous(range=c(.3,4),limits=c(0,1),name='Mean detection fraction')+facet_wrap(~comparison,ncol=3,scales='free')+labs(x=NULL,y=NULL)+th+theme(panel.grid=element_blank(),axis.text.y=element_text(size=7));savep(p,paste0(ds,'__shortlist_DotPlot'),d,14,13,'Sample-equal means among paired eligible samples. Left/Right defined in comparison table. Not usage. Same color range all datasets.')}
 dg<-diag[scope==ds];if(nrow(dg)){d<-rbind(dg[,.(comparison,gene_id,set,group='Left',expression=expr_left,detection=pct_left,n_samples)],dg[,.(comparison,gene_id,set,group='Right',expression=expr_right,detection=pct_right,n_samples)]);d[,condition:=paste(sub('_vs_rest','',comparison),group,sep=':')];p<-ggplot(d,aes(condition,gene_id,size=detection))+geom_point(data=d[expression>0],aes(color=expression))+geom_point(data=d[expression==0],color='black')+plasma(c(0,diagmax),'Mean RNA log-normalized')+scale_size_continuous(range=c(.2,3),limits=c(0,1),name='Mean detection fraction')+facet_wrap(~set,nrow=1,scales='free_y')+labs(x=NULL,y=NULL)+th+theme(panel.grid=element_blank(),axis.text.x=element_text(angle=90,hjust=1),axis.text.y=element_text(size=7));savep(p,paste0(ds,'__MP07_MP10_gene_diagnostics'),d,16,12,'Fixed 38/38/12 gene partition; per-gene sample-equal expression/detection. No new gene-set score.')}
 # Composition uses one resolution per panel; full source pool retained for denominators.
 d<-if(ds=='ALL')md else md[dataset==ds];d<-merge(d,samples,by='sample');comp<-rbindlist(lapply(c('r04','r06'),function(r){a<-d[,.(n=.N),by=.(sample_code,source,state=ifelse(get(r)%in%if(r=='r04')'C8'else c('C12','C16'),get(r),'Other'))];a[,fraction:=n/sum(n),by=sample_code];a[,resolution:=r]}));p<-ggplot(comp,aes(sample_code,fraction,fill=state))+geom_col(width=.85)+facet_wrap(~resolution,ncol=1)+scale_fill_manual(values=c(Other='grey85',C8='#BD3786',C12='#3B528B',C16='#E16462'),drop=FALSE)+labs(x='Sample code (all cells; see key)',y='Fraction of complete sample')+th+theme(axis.text.x=element_text(angle=90,hjust=1,size=6));savep(p,paste0(ds,'__sample_composition'),comp,14,6,'C8 and C12/C16 separated by resolution; includes full sample denominators and Other.')
}
# Full 14 raw usage profiles; color explicitly log1p of raw cluster mean.
prof<-fread(out('01_usage_bridge/all_cluster_14MP_profiles.tsv'))[scale=='usage_raw'];prof[,display:=log1p(mean)];p<-ggplot(prof,aes(MP,cluster))+geom_tile(data=prof[display>0],aes(fill=display))+geom_tile(data=prof[display==0],fill='black')+scale_fill_viridis_c(option='plasma',limits=c(0,log1p(max(usage))),name='log1p(mean usage raw)')+facet_wrap(~resolution,ncol=2,scales='free_y')+labs(x=NULL,y=NULL)+th+theme(axis.text.x=element_text(angle=90,hjust=1));savep(p,'ALL__14_usage_cluster_profiles',prof,13,9,'Cell-weighted raw usage cluster profiles; display transform only.')
# Dataset profiles retain all original clusters, no reclustering.
for(ds in scopes[scopes!='ALL']){d<-md[dataset==ds];pr<-rbindlist(lapply(c('r04','r06'),function(r)rbindlist(lapply(mp,function(m)data.table(cluster=d[[r]],value=usage[d$cell_id,m])[,.(mean=mean(value),n=.N),by=cluster][,`:=`(resolution=r,MP=m)]))));pr[,display:=log1p(mean)];p<-ggplot(pr,aes(MP,cluster))+geom_tile(data=pr[display>0],aes(fill=display))+geom_tile(data=pr[display==0],fill='black')+scale_fill_viridis_c(option='plasma',limits=c(0,log1p(max(usage))),name='log1p(mean usage raw)')+facet_wrap(~resolution,scales='free_y')+labs(x=NULL,y=NULL)+th+theme(axis.text.x=element_text(angle=90,hjust=1));savep(p,paste0(ds,'__14_usage_cluster_profiles'),pr,13,9,'Cell-weighted dataset subset; global usage range; original clusters.')}
